mapper.select:
SELECT a.ADJUSTMENT_ID, a.ADJUSTMENT_NO, a.MODEL_ID, a.PERIOD, a.VERSION, a.ADJUSTMENT_TYPE, a.ADJUSTMENT_REASON, a.STATUS, a.SUBMIT_USER, a.SUBMIT_TIME, a.APPROVE_USER, a.APPROVE_TIME, a.CREATE_USER, a.CREATE_TIME, m.MODEL_NAME, su.REALNAME AS SUBMIT_USER_NAME, cu.REALNAME AS CREATE_USER_NAME FROM TBL_BUDGET_ADJUSTMENT a LEFT JOIN TBL_BUDGET_MODEL m ON a.MODEL_ID = m.MODEL_ID LEFT JOIN TBL_STAFF su ON a.SUBMIT_USER = TO_CHAR(su.STAFFID) LEFT JOIN TBL_STAFF cu ON a.CREATE_USER = TO_CHAR(cu.STAFFID) WHERE a.ORG_ID = #{param.orgId}
AND a.ADJUSTMENT_NO LIKE CONCAT('%', #{param.adjustmentNo}, '%')
AND a.MODEL_ID = #{param.modelId}
AND a.PERIOD = #{param.period}
AND a.VERSION = #{param.version}
AND a.ADJUSTMENT_TYPE = #{param.adjustmentType}
AND a.STATUS = #{param.status}
AND a.CREATE_TIME >= #{param.startTime}
AND a.CREATE_TIME <= #{param.endTime}
ORDER BY a.CREATE_TIME DESC
